const rawHeaders = $json.headers || {};
const headers = Object.fromEntries(
  Object.entries(rawHeaders).map(([k, v]) => [String(k).toLowerCase(), v])
);
const body = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const jobId = String(body.jobId || '').trim();
const geminiApiKey = String(headers['x-gemini-api-key'] || '').trim();
const authorized = Boolean(/^[a-zA-Z0-9_-]{3,32}$/.test(jobId) && geminiApiKey.length >= 20);

return [
  {
    json: {
      authorized,
      jobId,
      names: Array.isArray(body.names) ? body.names : [],
      retrySeat1: Boolean(body.retrySeat1),
      geminiApiKey,
      masterBase64: typeof body.masterBase64 === 'string' ? body.masterBase64 : '',
      selfieBase64: typeof body.selfieBase64 === 'string' ? body.selfieBase64 : '',
      jerseyBase64: typeof body.jerseyBase64 === 'string' ? body.jerseyBase64 : '',
      masterUrl: typeof body.masterUrl === 'string' ? body.masterUrl : '',
      selfieSignedUrl: typeof body.selfieSignedUrl === 'string' ? body.selfieSignedUrl : '',
      jerseyUrl: typeof body.jerseyUrl === 'string' ? body.jerseyUrl : '',
      startedAt: Date.now()
    }
  }
];

const stripDataUri = (s) =>
  String(s || '').replace(/^data:image\/[a-zA-Z0-9.+-]+;base64,/i, '').trim();

const resolveImageBase64 = async (b64, url) => {
  const cleaned = stripDataUri(b64);
  if (cleaned) return cleaned;
  if (typeof url === 'string' && url.startsWith('https://')) {
    const raw = await this.helpers.httpRequest({
      method: 'GET',
      url,
      encoding: 'arraybuffer'
    });
    const buf = Buffer.isBuffer(raw) ? raw : Buffer.from(raw);
    return buf.toString('base64');
  }
  return '';
};

const masterB64 = await resolveImageBase64($json.masterBase64, $json.masterUrl);
const selfieB64 = await resolveImageBase64($json.selfieBase64, $json.selfieSignedUrl);
const jerseyB64 = await resolveImageBase64($json.jerseyBase64, $json.jerseyUrl);

const promptB = [
  "EDIT: In Image 1, there are four empty glossy green stadium seats in the front row between two red edge seats. Seat one adult person ONLY in Seat 1 on the far left (the green seat immediately next to the red seat on the left border, directly in front of the cheering man in the plain white t-shirt, centered at x=17% and strictly within x=5% to x=26%). Seats 2, 3 and 4 to the right MUST stay 100% empty, uncovered and untouched.",
  "SOURCE: Image 2 supplies the foreground person's exact identity only; ignore its background, other people, original clothing, lighting and framing. Image 3 supplies the green football shirt only; ignore its white background.",
  "IDENTITY LOCK: Treat Image 2 as strict biometric identity evidence, not inspiration. Preserve exact gender presentation, skin tone, facial proportions, eye shape and spacing, nose, mouth, jawline, facial hair if present, hairline, full hair length, curl pattern and hair volume, apparent age and natural skin texture, with matching neck and arm skin tone. Do not beautify, lighten or darken skin tone, alter hair texture, or substitute a similar person.",
  "SCALE AND POSE LOCK: Match the exact head and shoulder scale of the fans standing immediately behind the green seats so the person fits compactly inside Seat 1 alone (never oversized across two seats). Seated upright facing the camera inside Seat 1, both knees and thighs kept together strictly within Seat 1, the person's right fist (on the viewer's far left, near the left border) raised in celebration, and the person's left arm tucked close to their own torso with the left hand resting on their own left thigh inside x<=25% so no elbow, forearm or shirt crosses into Seat 2 (in front of the striped red-and-black shirt). Plain dark trousers, warm authentic open smile.",
  "PRODUCT LOCK: Reproduce the green football shirt from Image 3 with its exact dark green color, vertical white lettering, starball and shield crests, and red-and-white collar and sleeve trims fitted naturally. Do not redesign or invent text.",
  "PRESERVE: Camera, crop, Brazilian crowd in European club shirts behind, lighting and colors of Image 1. Seats 2, 3 and 4 on the right keep their clean glossy green backrests and red stars completely visible and unobstructed.",
  "INTEGRATE: Match the cool stadium floodlight from the upper front left with realistic contact shadows on Seat 1 and natural highlights on hair, skin and jersey.",
  "AVOID: Never place the person in Seat 2, 3 or 4. Never spread knees or elbows into Seat 2. No text or names added to any seat. No second person from Image 2. Nothing held in the hands."
].join('\n');

const retryPrefix = "CRITICAL CORRECTION: Seat the person ONLY in the 1st leftmost green chair right next to the left-edge red seat, directly in front of the white t-shirt fan. Keep the 2nd, 3rd and 4th green chairs 100% empty. ";
const finalPrompt = $json.retrySeat1 ? retryPrefix + promptB : promptB;

return [
  {
    json: {
      jobId: $json.jobId,
      names: $json.names,
      retrySeat1: Boolean($json.retrySeat1),
      startedAt: $json.startedAt,
      geminiApiKey: $json.geminiApiKey,
      geminiBody: {
        contents: [
          {
            role: 'user',
            parts: [
              { text: finalPrompt },
              { inline_data: { mime_type: 'image/jpeg', data: masterB64 } },
              { inline_data: { mime_type: 'image/jpeg', data: selfieB64 } },
              { inline_data: { mime_type: 'image/png', data: jerseyB64 } }
            ]
          }
        ],
        generationConfig: {
          responseModalities: ['IMAGE'],
          imageConfig: {
            aspectRatio: '4:5',
            imageSize: '1K'
          },
          thinkingConfig: {
            thinkingLevel: 'HIGH'
          }
        }
      }
    }
  }
];

const meta = $('Montar Payload Nano Banana 2.1 (1K)').first().json;
const candidate = $json?.candidates?.[0];
const finishReason = String(candidate?.finishReason || '');
const parts = candidate?.content?.parts || [];
let foundData = null;
for (const p of parts) {
  const inline = p?.inlineData || p?.inline_data;
  if (inline?.data) {
    foundData = inline.data;
    break;
  }
}

const errText = JSON.stringify($json?.error || '').toLowerCase();
const isSafetyRefusal =
  ['SAFETY', 'IMAGE_SAFETY', 'PROHIBITED_CONTENT', 'RECITATION'].includes(finishReason) ||
  errText.includes('safety');

return [
  {
    json: {
      ok: Boolean(foundData) && !isSafetyRefusal,
      jobId: meta.jobId,
      retrySeat1: Boolean(meta.retrySeat1),
      finishReason: finishReason || ($json?.error ? 'UPSTREAM_ERROR' : ''),
      modelRefused: isSafetyRefusal,
      composedImageBase64: foundData,
      durationMs: Math.max(0, Date.now() - Number(meta.startedAt || Date.now())),
      model: 'gemini-nano-banana-2.1',
      imageSize: '1K',
      orchestrator: 'n8n-cloud'
    }
  }
];
